{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C24"],
      "claim": "Zidovudine absolute oral bioavailability in humans is 54-74%, directly above the 20% threshold; with the highest transfer score (0.98), this is a strong supportive anchor.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Didanosine absolute oral bioavailability in patients with normal renal function is 42±12%, above the threshold; adult data support high bioavailability despite pediatric outliers.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C45"],
      "claim": "Paliperidone absolute oral bioavailability is 28% in humans, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Thiocolchicoside oral solution bioavailability relative to intramuscular is 27±7%, above the threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "BMS-275183, a complex diterpenoid-like taxane, has 24% oral bioavailability in humans, supporting high F for a structurally complex natural product.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Emtricitabine absolute oral bioavailability is 93%, strongly above the threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C52"],
      "claim": "Zalcitabine oral bioavailability in children is 91%, above the threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Ursodeoxycholic acid systemic availability is 50% in healthy subjects, above the threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Cedazuridine oral bioavailability is 20%, exactly at the threshold and therefore supportive of high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C50"],
      "claim": "Amphotericin B has negligible oral bioavailability due to poor permeability, low solubility, and gastric instability; this is the main contradictory evidence, but its extreme polyene size and polarity are not shared by the much smaller, less polar query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted high because the preponderance of high-transferability experimental oral bioavailability values (mostly 24-93%) supports F >=20%; the only low-F evidence (amphotericin B) is mechanistically tied to extreme physicochemical properties not shared by the query.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the query molecule itself is provided; prediction relies on transferable analogues.",
    "Some records under Molecule 9 refer to other drugs (voriconazole, theophylline, posaconazole) and were not used because they do not match the molecule SMILES.",
    "Pediatric didanosine values (19-21%) are borderline and introduce minor uncertainty, but adult values are consistently above threshold."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

